import type { SelectProps } from "./select.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "Select";

export const SelectClasses = {
  root: "exp-textura_select",
  trigger: "exp-textura_select_trigger",
  value: "exp-textura_select_value",
  triggerIcon: "exp-textura_select_trigger_icon",
  placeholderWrapper: "exp-textura_select_placeholder_wrapper",
  startAdornment: "exp-textura_select_start_adornment",
  content: "exp-textura_select_content",
  viewport: "exp-textura_select_viewport",
  item: "exp-textura_select_item",
  itemContent: "exp-textura_select_item_content",
  label: "exp-textura_select_item_label",
  subtext: "exp-textura_select_item_subtext",
  leadingIcon: "exp-textura_select_item_leading_icon",
  trailingIcon: "exp-textura_select_item_trailing_icon",
  textWrapper: "exp-textura_select_item_text_wrapper",
  itemText: "exp-textura_select_item_text",
  groupLabel: "exp-textura_select_group_label",
  divider: "exp-textura_select_divider",
  itemIndicator: "exp-textura_select_item_indicator",
  hasSelectedItemPadding: "exp-textura_select_item_has_selection_padding",
  hasSelectedItemIndicatorPadding: "exp-textura_select_item_indicator_has_selection_padding",
  sm: "exp-textura_select_sm",
  itemSm: "exp-textura_select_item_sm",
  hasSelection: "exp-textura_select_has_selection",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    trigger: {
      color: theme.inputDropdown.critical.color.content.enabled,
      border: `${theme.toRem(theme.inputDropdown.border.width)} solid ${theme.inputDropdown.critical.color.border.enabled}`,
    },
    triggerHover: {
      borderColor: theme.inputDropdown.critical.color.border.hover,
      color: theme.inputDropdown.critical.color.content.hover,
    },
    triggerFocus: {
      borderColor: theme.inputDropdown.critical.color.border.pressed,
      color: theme.inputDropdown.critical.color.content.pressed,
    },
    triggerDisabled: {
      borderColor: theme.inputDropdown.critical.color.border.disabled,
      color: theme.inputDropdown.critical.color.content.disabled,
      [`& .${SelectClasses.triggerIcon}`]: {
        color: theme.inputDropdown.critical.color.content.disabled,
      },
    },
    leadingIcon: {
      color: theme.color.content.utility.critical,
    },
    leadingIconHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    leadingIconPressed: {
      color: theme.color.content.inverse,
    },
    leadingIconSelected: {
      color: theme.color.content.utility.criticalStrong,
    },
    leadingIconDisabled: {
      color: theme.color.content.utility.criticalWeak,
    },
    trailingIcon: {
      color: theme.color.content.utility.critical,
    },
    trailingIconHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    trailingIconSelected: {
      color: theme.color.neutral.black,
    },
    subtext: {
      color: theme.color.content.weak,
    },
    subtextHover: {
      color: theme.color.content.utility.criticalStrong,
    },
    subtextPressed: {
      color: theme.color.content.inverse,
    },
    subtextSelected: {
      color: theme.color.content.strong,
    },
  },
  inline: {
    trigger: {
      backgroundColor: "transparent",
      borderColor: "transparent",
      color: theme.color.content.weak,
    },
    triggerHover: {
      backgroundColor: theme.color.background.defaultHover,
      borderColor: "transparent",
      color: theme.color.content.default,
    },
    triggerFocus: {
      backgroundColor: theme.color.background.defaultPressed,
      borderColor: "transparent",
      color: theme.color.content.default,
    },
    triggerDisabled: {
      backgroundColor: "transparent",
      borderColor: "transparent",
      color: theme.color.content.disabled,
    },
    triggerIconHover: {
      color: theme.color.content.iconStrong,
    },
    triggerIconFocus: {
      color: theme.color.content.iconStrong,
    },
    triggerIconDisabled: {
      color: theme.color.content.iconWeak,
    },
    startAdornmentHover: {
      color: theme.color.content.iconStrong,
    },
    startAdornmentFocus: {
      color: theme.color.content.iconStrong,
    },
  },
});

const generateStyles = (props: SelectProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SelectProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    all: "unset",
    display: "block",
    boxSizing: "border-box",
    width: "100%",
    minWidth: theme.toRem(96),

    [`.${SelectClasses.trigger}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "flex-start",
      gap: theme.toRem(theme.spacing[8]), // Add gap for consistent spacing
      position: "relative",
      backgroundColor: theme.color.background.default,
      color: theme.inputDropdown.default.color.content.enabled,
      border: `${theme.toRem(theme.inputDropdown.border.width)} solid ${theme.inputDropdown.default.color.border.enabled}`,
      borderRadius: theme.toRem(theme.inputDropdown.border.radius),
      padding: `0 0 0 ${theme.toRem(theme.spacing[8])}`,
      minHeight: theme.toRem(32),
      width: "100%",
      cursor: "pointer",
      userSelect: "none",
      ...theme.typography.body.md,
      ":dir(rtl)": {
        padding: `0 ${theme.toRem(theme.spacing[8])} 0 0`,
      },
      [`.${SelectClasses.value}`]: {
        flex: "1 1 auto",
        textWrap: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
        minWidth: theme.toRem(theme.spacing[16]),
        color: "inherit",
      },
      "&:hover": {
        borderColor: theme.inputDropdown.default.color.border.hover,
        color: theme.inputDropdown.default.color.content.hover,
        [`& .${SelectClasses.triggerIcon}`]: {
          color: theme.buttonIcon.secondary.color.content.enabled,
          ...styleSlots?.triggerIconHover,
        },
        [`& .${SelectClasses.startAdornment}`]: {
          color: theme.color.content.icon,
          ...styleSlots?.startAdornmentHover,
        },
        ...styleSlots?.triggerHover,
      },
      "&:focus-visible": {
        outline: "none",
        borderColor: theme.inputDropdown.default.color.border.pressed,
        color: theme.inputDropdown.default.color.content.pressed,
        [`& .${SelectClasses.triggerIcon}`]: {
          color: theme.buttonIcon.secondary.color.content.enabled,
          ...styleSlots?.triggerIconFocus,
        },
        [`& .${SelectClasses.startAdornment}`]: {
          color: theme.color.content.icon,
          ...styleSlots?.startAdornmentFocus,
        },
        ...styleSlots?.triggerFocus,
      },
      "&[disabled]": {
        backgroundColor: theme.color.background.default,
        borderColor: theme.inputDropdown.default.color.border.disabled,
        color: theme.inputDropdown.default.color.content.disabled,
        cursor: "not-allowed",
        [`& .${SelectClasses.triggerIcon}`]: {
          color: theme.buttonIcon.secondary.color.content.disabled,
          ...styleSlots?.triggerIconDisabled,
        },
        [`& .${SelectClasses.value}`]: {
          color: theme.inputDropdown.default.color.content.disabled,
        },
        [`& .${SelectClasses.startAdornment}`]: {
          color: theme.color.content.iconWeak,
          ...styleSlots?.startAdornmentDisabled,
        },
        ...styleSlots?.triggerDisabled,
      },
      ...styleSlots?.trigger,
    },

    [`.${SelectClasses.triggerIcon}`]: {
      color: theme.buttonIcon.secondary.color.content.enabled,
      display: "flex",
      alignItems: "center",
      marginInlineStart: "auto", // Push to right
      fontSize: theme.toRem(16),
      minWidth: theme.toRem(16),
      width: theme.toRem(32),
      ...styleSlots?.triggerIcon,
    },

    [`.${SelectClasses.placeholderWrapper}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      color: theme.color.content.weak,
      "& > svg": {
        width: theme.toRem(16),
        height: theme.toRem(16),
        color: theme.color.content.icon,
      },
      ...styleSlots?.placeholderWrapper,
    },

    [`.${SelectClasses.startAdornment}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.icon,
      "& > svg": {
        width: theme.toRem(16),
        height: theme.toRem(16),
      },
      ...styleSlots?.startAdornment,
    },

    [`.${SelectClasses.content}`]: {
      width: "var(--radix-select-trigger-width)",
      ...theme.typography.body.md,
      overflow: "hidden",
      backgroundColor: theme.color.background.default,
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderRadius: theme.toRem(theme.border.radius.sm),
      boxShadow: theme.dropShadow.lg,
      padding: 0,
      zIndex: theme.zIndex.dynamic,
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[4]),
      "&:focus-visible": {
        boxShadow: theme.dropShadow.lg,
      },
      ...styleSlots?.content,
    },

    [`.${SelectClasses.viewport}`]: {
      padding: theme.toRem(theme.spacing[8]),
      ...styleSlots?.viewport,
    },

    [`.${SelectClasses.divider}`]: {
      height: theme.toRem(theme.border.width.sm),
      backgroundColor: theme.color.border.default,
      margin: `${theme.toRem(theme.spacing[8])} calc(${theme.toRem(theme.spacing[8])} * -1)`,
      ...styleSlots?.divider,
    },

    [`.${SelectClasses.item}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      position: "relative",
      minHeight: theme.toRem(32),
      cursor: "pointer",
      userSelect: "none",
      borderRadius: theme.toRem(theme.border.radius.sm),
      color: theme.menu.default.color.content.enabled,

      "&[data-has-subtext]": {
        alignItems: "flex-start",
        paddingTop: theme.toRem(theme.spacing[4]),
        paddingBottom: theme.toRem(theme.spacing[4]),

        [`& .${SelectClasses.itemIndicator}`]: {
          marginTop: theme.toRem(2), // Align with first line roughly
        },
        [`& .${SelectClasses.leadingIcon}`]: {
          height: theme.typography.body.md.lineHeight,
        },
        [`& .${SelectClasses.trailingIcon}`]: {
          height: theme.typography.body.md.lineHeight,
        },
      },

      [`& > span:not(.${SelectClasses.itemIndicator})`]: {
        textWrap: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
      },
      "&[data-highlighted]": {
        backgroundColor: theme.menu.default.color.background.hover,
        color: theme.menu.default.color.content.hover,
        outline: "none",
        [`.${SelectClasses.itemIndicator}`]: {
          color: theme.menu.default.color.content.hover,
        },
        [`& .${SelectClasses.subtext}`]: {
          color: theme.color.content.default,
          ...styleSlots?.subtextHover,
        },
        [`& .${SelectClasses.leadingIcon}`]: {
          color: theme.color.content.iconStrong,
          ...styleSlots?.leadingIconHover,
        },
        [`& .${SelectClasses.trailingIcon}`]: {
          color: theme.color.content.iconStrong,
          ...styleSlots?.trailingIconHover,
        },
        ...styleSlots?.itemHighlighted,
      },
      "&:active": {
        backgroundColor: theme.menu.default.color.background.pressed,
        color: theme.menu.default.color.content.pressed,
        [`.${SelectClasses.itemIndicator}`]: {
          color: theme.menu.default.color.content.pressed,
        },
        [`& .${SelectClasses.subtext}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.subtextPressed,
        },
        [`& .${SelectClasses.leadingIcon}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.leadingIconPressed,
        },
        [`& .${SelectClasses.trailingIcon}`]: {
          color: theme.color.content.inverse,
          ...styleSlots?.trailingIconPressed,
        },
        ...styleSlots?.itemPressed,
      },
      "&[data-state='checked']": {
        backgroundColor: theme.menu.default.color.background.selected,
        color: theme.menu.default.color.content.selected,
        [`.${SelectClasses.itemIndicator}`]: {
          color: theme.menu.default.color.content.selected,
        },
        [`& .${SelectClasses.subtext}`]: {
          color: "inherit",
          ...styleSlots?.subtextSelected,
        },
        [`& .${SelectClasses.leadingIcon}`]: {
          color: theme.color.content.actionSelected,
          ...styleSlots?.leadingIconSelected,
        },
        [`& .${SelectClasses.trailingIcon}`]: {
          color: theme.color.content.actionSelected,
          ...styleSlots?.trailingIconSelected,
        },
        ...styleSlots?.itemSelected,
      },
      "&[data-disabled]": {
        color: theme.menu.default.color.content.disabled,
        pointerEvents: "none",
        [`& .${SelectClasses.subtext}`]: {
          color: "inherit",
          ...styleSlots?.subtextDisabled,
        },
        [`& .${SelectClasses.leadingIcon}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.leadingIconDisabled,
        },
        [`& .${SelectClasses.trailingIcon}`]: {
          color: theme.color.content.disabled,
          ...styleSlots?.trailingIconDisabled,
        },
        ...styleSlots?.itemDisabled,
      },
      "&:focus-visible": {
        boxShadow: "none",
      },
      ...styleSlots?.item,
    },

    [`.${SelectClasses.itemContent}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      svg: {
        minWidth: theme.toRem(14),
      },
      ...styleSlots?.itemContent,
    },

    [`.${SelectClasses.textWrapper}`]: {
      display: "flex",
      flexDirection: "column",
      flex: "1 1 auto",
    },

    [`.${SelectClasses.itemText}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.itemText,
    },

    [`.${SelectClasses.label}`]: {
      flex: "1 1 auto",
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),
      ...theme.typography.body.md,
      ...styleSlots?.label,
    },

    [`.${SelectClasses.subtext}`]: {
      ...theme.typography.body.sm,
      lineHeight: theme.typography.lineHeight[16],
      color: theme.color.content.weak,
      ...styleSlots?.subtext,
    },

    [`.${SelectClasses.leadingIcon}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.icon,
      "& > svg": {
        width: theme.toRem(16),
        height: theme.toRem(16),
        color: "inherit",
      },
      ...styleSlots?.leadingIcon,
    },

    [`.${SelectClasses.trailingIcon}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.icon,
      "& > svg": {
        width: theme.toRem(16),
        height: theme.toRem(16),
        color: "inherit",
      },
      ...styleSlots?.trailingIcon,
    },

    [`.${SelectClasses.hasSelectedItemPadding}`]: {
      paddingInlineStart: `calc(${theme.toRem(theme.spacing[8])} + ${theme.toRem(theme.typography.fontSize[16])} + ${theme.toRem(theme.spacing[8])})`,
      [`& > span:not(.${SelectClasses.itemIndicator})`]: {
        ...styleSlots?.hasSelectedItemPadding,
      },
    },

    [`.${SelectClasses.itemIndicator}`]: {
      display: "flex",
      alignItems: "center",
      fontSize: theme.typography.fontSize[16],
      width: theme.typography.fontSize[16],
      color: theme.color.content.default,
      position: "absolute",
      left: theme.toRem(theme.spacing[8]),
      "$dir(rtl)": {
        left: "auto",
        right: theme.toRem(theme.spacing[8]),
      },
      ...styleSlots?.itemIndicator,
    },

    [`.${SelectClasses.hasSelectedItemIndicatorPadding}`]: {
      margin: 0,
      ...styleSlots?.hasSelectedItemIndicatorPadding,
    },

    [`.${SelectClasses.groupLabel}`]: {
      display: "flex",
      alignItems: "baseline",
      color: theme.color.content.default,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[16])} ${theme.toRem(theme.spacing[4])} ${theme.toRem(
        theme.spacing[8],
      )}`,
      ...theme.typography.label.sm,
      ...styleSlots?.groupLabel,
    },

    [`&.${SelectClasses.sm}`]: {
      [`.${SelectClasses.trigger}`]: {
        minHeight: theme.toRem(24),
        ...theme.typography.body.sm,
        ...styleSlots?.triggerSm,
      },

      [`.${SelectClasses.triggerIcon}`]: {
        fontSize: theme.toRem(12),
        width: theme.toRem(24),
      },

      [`.${SelectClasses.label}`]: {
        ...theme.typography.body.sm,
      },
    },

    [`.${SelectClasses.itemSm}`]: {
      minHeight: theme.toRem(24),
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[12])}`,
      ...theme.typography.body.sm,
      gap: theme.toRem(theme.spacing[8]),

      [`&.${SelectClasses.hasSelectedItemPadding}`]: {
        paddingInlineStart: theme.toRem(28),
      },

      [`& .${SelectClasses.itemIndicator}`]: {
        fontSize: theme.toRem(12),
        width: theme.toRem(12),
      },

      [`& .${SelectClasses.leadingIcon}`]: {
        "& > svg": {
          width: theme.toRem(12),
          height: theme.toRem(12),
        },
      },
      [`& .${SelectClasses.trailingIcon}`]: {
        "& > svg": {
          width: theme.toRem(12),
          height: theme.toRem(12),
        },
      },
      [`.${SelectClasses.label}`]: {
        ...theme.typography.body.sm,
      },
    },

    [`&:not(.${SelectClasses.hasSelection})`]: {
      [`.${SelectClasses.trigger}`]: {
        "&:hover": {
          [`& .${SelectClasses.startAdornment}`]: {
            color: theme.color.content.icon,
          },
        },
        "&:focus-visible": {
          [`& .${SelectClasses.startAdornment}`]: {
            color: theme.color.content.icon,
          },
        },
      },
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledSelect = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SelectProps>((props) => generateStyles(props));
